<?php
declare(strict_types=1);require_once __DIR__.'/../config/auth.php';$me=page_require(['ADMIN','VERIFICADOR']);$admin=$me['rol']==='ADMIN';?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mensajes — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Manrope,Arial,sans-serif;color:#172033}.wrap{max-width:920px;margin:auto;padding:82px 14px 32px}h1{margin:0 0 5px}.sub{color:#64748b;margin-bottom:18px}.panel,.msg{background:#fff;border-radius:15px;padding:15px;margin-bottom:10px}.form{display:grid;grid-template-columns:1fr 1fr;gap:8px}.form input,.form select,.form textarea{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:9px;font:inherit}.form textarea{grid-column:1/-1;min-height:90px}.btn{border:0;border-radius:9px;padding:10px 12px;font-weight:800;cursor:pointer;background:#123b5d;color:#fff}.msg.inactive{opacity:.55}.meta{font-size:11px;color:#64748b;margin-top:5px}.title{font-weight:900}.body{margin-top:7px;white-space:pre-wrap}@media(max-width:650px){.form{grid-template-columns:1fr}.form textarea{grid-column:auto}}</style></head><body><main class="wrap"><h1>Mensajes</h1><div class="sub">Avisos visibles para alumnos</div><?php if($admin):?><div class="panel"><div class="form"><input id="titulo" placeholder="Título"><select id="aud"><option value="TODOS">Todos</option><option value="REGULARES">Regulares</option><option value="INTENSIVOS">Intensivos</option><option value="ALUMNO">Alumno específico</option></select><select id="alumno"><option value="">Alumno...</option></select><input id="desde" type="date"><input id="hasta" type="date"><textarea id="cuerpo" placeholder="Mensaje"></textarea><button id="crear" class="btn">Publicar mensaje</button></div></div><?php endif;?><div id="lista"></div></main><script>const admin=<?=json_encode($admin)?>,L=document.getElementById('lista');async function post(b){const r=await fetch('/api/mensajes.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}async function load(){const r=await fetch('/api/mensajes.php'),d=await r.json();L.innerHTML=d.mensajes.map(x=>`<article class="msg ${Number(x.activo)?'':'inactive'}"><div class="title">${x.titulo}</div><div class="body">${x.cuerpo}</div><div class="meta">${x.audiencia}${x.alumno_nombre?' · '+x.alumno_nombre:''}${x.vigencia_desde?' · '+x.vigencia_desde:''}${x.vigencia_hasta?' → '+x.vigencia_hasta:''}</div>${admin?`<button class="btn" data-id="${x.id}" data-a="${Number(x.activo)?0:1}">${Number(x.activo)?'Desactivar':'Activar'}</button>`:''}</article>`).join('')||'<div class="panel">No hay mensajes.</div>';if(admin)L.querySelectorAll('button').forEach(b=>b.onclick=async()=>{await post({accion:'ESTADO',id:b.dataset.id,activo:Number(b.dataset.a)});load()})}<?php if($admin):?>fetch('/api/alumnos.php').then(r=>r.json()).then(d=>d.alumnos.forEach(a=>{const o=document.createElement('option');o.value=a.id;o.textContent=a.nombre;alumno.appendChild(o)}));crear.onclick=async()=>{try{await post({accion:'CREAR',titulo:titulo.value,cuerpo:cuerpo.value,audiencia:aud.value,alumno_id:alumno.value||null,vigencia_desde:desde.value||null,vigencia_hasta:hasta.value||null});titulo.value='';cuerpo.value='';load()}catch(e){alert(e.message)}};<?php endif;?>load();</script></body></html>